    religion_composition: "イスラム教が国教で国民の大多数を占めます。外国人居住者が非常に多いため、居住人口全体ではキリスト教、ヒンドゥー教、仏教なども大きな割合を持ちます。",
    society: "自国民より外国人居住者が多い多国籍社会で、英語がビジネスとサービスで広く使われます。イスラム文化を基盤に、国際教育・スポーツ・メディア拠点を整備しています。",
    industries: "天然ガス、石油、石油化学、航空、金融、建設、物流、観光が主要分野です。食品の輸入依存度が高く、ホテル・外食向け市場が重要です。",
    food: "米、肉、魚、デーツ、香辛料を使う湾岸料理が基盤です。外国人の多さから、南アジア、レバント、欧米、東アジアの料理が幅広く提供されています。",
    japan_relation: "日本とはLNGを中心とするエネルギー取引で深い関係があり、投資、航空、教育、文化、スポーツでも交流があります。",
    history: "真珠採取と海上交易を基盤とする首長国として形成され、20世紀初頭から英国の保護下に入りました。1971年に独立し、天然ガス開発を通じて急速に発展しました。",
