    updated: "2026-07-16", overview: "アフガニスタンは中央・南アジアの山岳内陸国です。2021年以降はタリバンが実権を掌握し、国際承認、女性の権利、人道状況、金融・物流制約が経済と市場情報に大きく影響しています。",
