    religion_composition: "イスラム教徒が人口のほぼ全体を占め、多数派はスンニ派、ハザラ人などにはシーア派が多くいます。信頼できる新しい全国宗教統計は限られています。",
    society: "パシュトゥーン、タジク、ハザラ、ウズベクなど多様な民族・言語集団が暮らします。長期紛争、国内避難、教育・医療への制約が生活に大きな影響を与えています。",
    industries: "農牧業、乾燥果実、絨毯、鉱業、小規模商業が主要分野です。金融、国際送金、電力、輸送、制裁・規制の制約が事業環境に影響します。",
    food: "小麦のパン、米、羊肉、豆、乳製品、乾燥果実を使い、カブリ・プラオなどが知られます。イスラム教の食習慣が基本です。",
