    japan_relation: "日本は人道支援、食料、医療、水・衛生、農業、平和構築を支援してきました。現在の交流は治安情勢の影響を強く受けています。",
    history: "古代ヌビア諸王国とクシュ王国、イスラム化、オスマン・エジプト支配、マフディー国家、英国・エジプト共同統治を経て1956年に独立しました。長い南北内戦の後、2011年に南スーダンが独立しました。2019年の政変と移行失敗を経て、2023年から再び大規模戦闘が続いています。",
