    history: "スーダン南部として英国・エジプト共同統治を受け、1956年のスーダン独立後に南北内戦が続きました。2005年の包括和平合意と住民投票を経て2011年に独立しました。2013年からの内戦後、2018年和平合意に基づく移行が続いています。",
