    religion_composition: "キリスト教徒が人口の大多数で、ルター派が特に大きな割合を占めます。カトリック、他のプロテスタント、伝統宗教などもあります。",
    society: "オバンボ、カバンゴ、ヘレロ、ダマラ、ナマ、サンなど多様な民族が暮らします。人口密度が非常に低く、所得格差、土地、水、若年雇用が課題です。",
    industries: "ダイヤモンド、ウラン、金属、漁業、畜産、観光、港湾・物流が主要分野です。ウォルビスベイ港は内陸国への物流拠点です。",
    food: "とうもろこし、雑穀、肉、魚、乳製品、豆を食べます。沿岸部では魚介、内陸部では牛・羊・狩猟文化の影響があります。",
    japan_relation: "日本とはウラン・鉱物、漁業、港湾、再生可能エネルギー、保健、教育で関係があります。",
    history: "コイサン系、バントゥー系諸集団が暮らす地域に、19世紀末ドイツが植民地を建設し、ヘレロ・ナマに対する大量虐殺が起きました。第一次世界大戦後は南アフリカ統治下に置かれ、長い独立闘争を経て1990年に独立しました。",
