    facts: [["首都", "プレトリア（行政）・ケープタウン（立法）・ブルームフォンテーン（司法）"],["公用語", "ズールー語・コサ語・英語・アフリカーンス語など12言語"],["通貨", "ランド（ZAR）"],["政治体制", "共和制・議院内閣制"]],
