    industries: "綿花、農業、食品、港湾・物流、商業、建設が主要分野です。コトヌー港とナイジェリア市場との関係が重要です。",
    food: "とうもろこし、キャッサバ、ヤムイモ、米、豆、魚、パーム油を使います。南北で主食や味付けに違いがあります。",
