  HT: {
    updated: "2026-07-16", overview: "ハイチはイスパニョーラ島西部を占めるカリブ海の共和国です。農業、軽工業、海外送金が生活を支える一方、移行統治、武装集団による治安危機、災害、物価高への対応が最重要課題です。",
    facts: [["首都", "ポルトープランス"],["公用語", "ハイチ・クレオール語、フランス語"],["通貨", "グールド（HTG）"],["政治体制", "共和制・移行統治下"]],
    religion_composition: "キリスト教徒が大多数で、カトリックとプロテスタントが中心です。アフリカ由来のヴードゥーは、キリスト教と重なりながら文化と生活に広く根付いています。",
    society: "アフリカ系住民が大多数で、クレオール語が日常生活の中心です。国外移住と送金の比重が大きく、治安、避難、食料、医療、教育、災害復旧が大きな課題です。",
    industries: "縫製、農業、マンゴー・コーヒー、建設、通信、商業、海外送金が主要分野です。",
    food: "米、豆、トウモロコシ、キャッサバ、プランテン、豚肉、鶏肉を使い、クレオール料理にはアフリカ、フランス、カリブの影響があります。",
    japan_relation: "日本は食料、保健、防災、教育、農業、人道支援を通じて協力しています。",
    history: "フランス領サン＝ドマングで奴隷制プランテーションが発展した後、奴隷反乱と独立戦争を経て1804年に世界初の黒人共和国として独立しました。独裁、政変、外国介入、大地震を経験し、現在も国家制度と治安の再建が続いています。",
    sources: [["外務省『ハイチ共和国基礎データ』", "https://www.mofa.go.jp/mofaj/area/haiti/data.html"]]
  },
